  "filename": "page_periodlog.js",
  "content": "// PeriodLog page module
// Registers the PeriodLog page with the shared ForgeAI SPA shell.
// The module renders a list of period logs and a modal form to create new logs.

(function () {
  // Register the page under the slug "periodlog"
  window.ForgeAI.registerPage('periodlog', async function (ctx) {
    const { root, api, search } = ctx;
    // Clear any existing content
    root.innerHTML = '';

    // Create main container
    const container = document.createElement('div');
    container.className = 'periodlog-page';
    root.appendChild(container);

    // Header with title and add button
    const header = document.createElement('div');
    header.className = 'page-header';
    header.innerHTML = `
      <h2 class="page-title">Period Log</h2>
      <button id="add-period-btn" class="btn btn-primary">
        <i class="icon calendar-plus"></i> Add Period
      </button>
    `;
    container.appendChild(header);

    // Loading indicator
    const loading = document.createElement('div');
    loading.className = 'loading';
    loading.textContent = 'Loading...';
    container.appendChild(loading);

    // Table container (will hold the list once loaded)
    const tableWrapper = document.createElement('div');
    tableWrapper.className = 'table-wrapper';
    container.appendChild(tableWrapper);

    // Toast container
    const toastContainer = document.createElement('div');
    toastContainer.className = 'toast-container';
    document.body.appendChild(toastContainer);

    // Modal elements (hidden by default)
    const modalOverlay = document.createElement('div');
    modalOverlay.className = 'modal-overlay hidden';
    modalOverlay.innerHTML = `
      <div class="modal">
        <h3 class="modal-title">Add New Period</h3>
        <form id="period-form">
          <div class="form-group">
            <label for="start_date">Start Date</label>
            <input type="date" id="start_date" name="start_date" required />
          </div>
          <div class="form-group">
            <label for="end_date">End Date</label>
            <input type="date" id="end_date" name="end_date" required />
          </div>
          <div class="form-group">
            <label for="flow">Flow</label>
            <input type="text" id="flow" name="flow" placeholder="e.g., Light, Medium, Heavy" />
          </div>
          <div class="form-group">
            <label for="symptoms">Symptoms</label>
            <input type="text" id="symptoms" name="symptoms" placeholder="e.g., Cramps, Headache" />
          </div>
          <div class="form-group">
            <label for="notes">Notes</label>
            <textarea id="notes" name="notes" rows="3" placeholder="Additional notes..."></textarea>
          </div>
          <div class="modal-actions">
            <button type="button" class="btn btn-secondary" id="cancel-btn">Cancel</button>
            <button type="submit" class="btn btn-primary">Save</button>
          </div>
        </form>
      </div>
    `;
    document.body.appendChild(modalOverlay);

    // Helper: show toast
    function showToast(message, type = 'success') {
      const toast = document.createElement('div');
      toast.className = `toast toast-${type}`;
      toast.textContent = message;
      toastContainer.appendChild(toast);
      setTimeout(() => {
        toast.remove();
      }, 3000);
    }

    // Helper: open/close modal
    function openModal() {
      modalOverlay.classList.remove('hidden');
    }
    function closeModal() {
      modalOverlay.classList.add('hidden');
      const form = document.getElementById('period-form');
      form.reset();
    }

    // Load period logs from the API
    async function loadPeriodLogs() {
      loading.style.display = 'block';
      tableWrapper.innerHTML = '';
      try {
        const resp = await api('/api/periodlogs');
        if (!resp.success) throw new Error('API error');
        const logs = resp.data || [];
        renderTable(logs);
      } catch (err) {
        tableWrapper.innerHTML = `<p class="error">Failed to load period logs.</p>`;
        console.error(err);
      } finally {
        loading.style.display = 'none';
      }
    }

    // Render table of logs
    function renderTable(logs) {
      if (logs.length === 0) {
        tableWrapper.innerHTML = `
          <div class="empty-state">
            <p>No period logs yet.</p>
            <button id="empty-add-btn" class="btn btn-primary">Add your first period</button>
          </div>
        `;
        document.getElementById('empty-add-btn').addEventListener('click', openModal);
        return;
      }

      const table = document.createElement('table');
      table.className = 'period-table';
      table.innerHTML = `
        <thead>
          <tr>
            <th>Start Date</th>
            <th>End Date</th>
            <th>Flow</th>
            <th>Symptoms</th>
            <th>Notes</th>
          </tr>
        </thead>
        <tbody></tbody>
      `;
      const tbody = table.querySelector('tbody');
      logs.forEach(log => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td>${log.start_date || ''}</td>
          <td>${log.end_date || ''}</td>
          <td>${log.flow || ''}</td>
          <td>${log.symptoms || ''}</td>
          <td>${log.notes || ''}</td>
        `;
        tbody.appendChild(tr);
      });
      tableWrapper.appendChild(table);
    }

    // Handle Add button click
    document.getElementById('add-period-btn').addEventListener('click', openModal);
    document.getElementById('cancel-btn').addEventListener('click', closeModal);

    // Handle form submission
    document.getElementById('period-form').addEventListener('submit', async function (e) {
      e.preventDefault();
      const form = e.target;
      const data = {
        start_date: form.start_date.value,
        end_date: form.end_date.value,
        flow: form.flow.value,
        symptoms: form.symptoms.value,
        notes: form.notes.value,
      };
      try {
        const resp = await api('/api/periodlogs', {
          method: 'POST',
          json: data,
        });
        if (!resp.success) throw new Error('Failed to save');
        showToast('Period logged successfully');
        closeModal();
        loadPeriodLogs();
      } catch (err) {
        showToast('Error saving period log', 'error');
        console.error(err);
      }
    });

    // Initial load
    loadPeriodLogs();
  });
})();
"
}
